namespace sv_f9012a07a5704be3b6729eba632182d8.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Description,
    string Location,
    DateTimeOffset Timestamp);

using sv_f9012a07a5704be3b6729eba632182d8.Client.Models;

namespace sv_f9012a07a5704be3b6729eba632182d8.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_f9012a07a5704be3b6729eba632182d8.Client.Models;
using sv_f9012a07a5704be3b6729eba632182d8.Client.Services;

namespace sv_f9012a07a5704be3b6729eba632182d8.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            "PKG-001",
            "In Transit",
            "Memphis, TN",
            new DateTimeOffset(2026, 7, 10, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", "New York, NY", new DateTimeOffset(2026, 7, 5, 9, 0, 0, TimeSpan.Zero)),
                new("Arrived at sorting facility", "Newark, NJ", new DateTimeOffset(2026, 7, 5, 14, 30, 0, TimeSpan.Zero)),
                new("Departed facility", "Newark, NJ", new DateTimeOffset(2026, 7, 6, 3, 0, 0, TimeSpan.Zero)),
                new("Arrived at regional hub", "Memphis, TN", new DateTimeOffset(2026, 7, 6, 18, 45, 0, TimeSpan.Zero)),
            }),

        ["PKG-002"] = new Shipment(
            "PKG-002",
            "Delivered",
            "San Francisco, CA",
            new DateTimeOffset(2026, 7, 7, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Package picked up", "Seattle, WA", new DateTimeOffset(2026, 7, 3, 10, 0, 0, TimeSpan.Zero)),
                new("In transit", "Portland, OR", new DateTimeOffset(2026, 7, 4, 8, 0, 0, TimeSpan.Zero)),
                new("Out for delivery", "San Francisco, CA", new DateTimeOffset(2026, 7, 5, 7, 30, 0, TimeSpan.Zero)),
                new("Delivered - Left at front door", "San Francisco, CA", new DateTimeOffset(2026, 7, 5, 11, 22, 0, TimeSpan.Zero)),
            }),

        ["PKG-003"] = new Shipment(
            "PKG-003",
            "Processing",
            "Chicago, IL",
            new DateTimeOffset(2026, 7, 12, 15, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new("Label created", "Chicago, IL", new DateTimeOffset(2026, 7, 7, 8, 0, 0, TimeSpan.Zero)),
            }),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@using sv_f9012a07a5704be3b6729eba632182d8.Client.Models
@using sv_f9012a07a5704be3b6729eba632182d8.Client.Services
@implements IDisposable
@inject IShipmentService ShipmentService
@inject ILogger<Shipment> Logger
@rendermode InteractiveAuto

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_error is not null)
{
    <div class="error-message">
        <p>@_error</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Current Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        <ul class="status-updates">
            @foreach (var update in _shipment.StatusUpdates)
            {
                <li>
                    <strong>@update.Timestamp.ToString("g")</strong> —
                    @update.Description (@update.Location)
                </li>
            }
        </ul>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Client.Models.Shipment? _shipment;
    private bool _loading;
    private string? _error;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _error = null;
        _loading = true;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation or disposal triggered cancellation — do nothing
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _error = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

